def _iter_nav_md_targets(node: object) -> list[str]: targets: list[str] = []; (targets.append(node) if node.endswith('.md') else None) if isinstance(node, str) else [targets.extend(_iter_nav_md_targets(item)) for item in node] if isinstance(node, list) else [targets.extend(_iter_nav_md_targets(value)) for value in node.values()] if isinstance(node, dict) else None; return targets
